/**
 * 생성 파일 — 손으로 고치지 않는다. `pnpm gen:blog-images --og`(`scripts/gen-blog-images.ts`)가 공개 글마다 링크 미리보기 카드(1200×630 PNG —
 * 로고 가로 조합 + 글 제목, 흑백)를 헤드리스 Chrome 으로 그려 쓴다. import 는 없다(값 파일). 키는 `<slug>/<lang>`.
 * `title` 은 카드를 그릴 때의 글 제목이다 — 글 제목이 바뀌었는데 다시 그리지 않았으면 사이트는 이 카드 대신 사이트 공통 OG 를 싣는다(낡은 제목 방지).
 */

export interface BlogOgImage {
  readonly path: string;
  readonly contentType: string;
  readonly width: number;
  readonly height: number;
  readonly hash: string;
  readonly bytes: number;
  readonly base64: string;
  readonly title: string;
}

